:</b> Kurulumdan sonra install.php dosyasını sunucudan kaldırın.</p></div><?php else:?><form method="post"><div class="grid"><label>MySQL Sunucu<input name="db_host" value="<?=ih($_POST['db_host']??'localhost')?>" required></label><label>Port<input name="db_port" value="<?=ih($_POST['db_port']??'3306')?>" required></label><label>Veritabanı Adı<input name="db_name" value="<?=ih($_POST['db_name']??'')?>" required></label><label>Veritabanı Kullanıcısı<input name="db_user" value="<?=ih($_POST['db_user']??'')?>" required></label><label class="full">Veritabanı Şifresi<input type="password" name="db_pass"></label><label class="full">Site Adresi<input name="site_url" value="<?=ih($_POST['site_url']??'https://iksiryayincilik.com/topluca')?>" required></label></div><div class="danger"><label><input style="width:auto;display:inline-block;margin-right:8px" type="checkbox" name="fresh" value="1"> Mevcut TOPLUCA tablolarını silip sıfırdan kur</label><p class="muted">Yalnızca bu demo veritabanını sıfırlamak istiyorsanız kullanın. Başka sitenin veritabanında kullanmayın.</p><label>Onay<input name="confirm" placeholder="Sıfırlama seçiliyse: TOPLUCA SIFIRLA"></label></div><button>TOPLUCA V4'Ü KUR</button></form><?php endif;?></div></div></body></html>